// Configure once in the private n8n instance. Never accept these settings from input.
const companyId = 'CONFIGURE_COMPANY_UUID';
const companyName = 'CONFIGURE_COMPANY_NAME';
const sourceRoot = '/drive/root:/CONFIGURE_SOURCE_FOLDER';
const batchExecutionApproved = false; // Enable after worker 12A.3 + credential pilot.
const input = $input.all();
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (!batchExecutionApproved) return [{json:{batchExecutionApproved:false,targets:[]}}];
if (!uuid.test(companyId) || companyName.startsWith('CONFIGURE_') || sourceRoot.includes('CONFIGURE_')) throw new Error('configuration_required');
if (input.length < 1 || input.length > 10) throw new Error('send_1_to_10_documents_per_call');
const ids = [...new Set(input.map(item => item.json.document_id))];
if (ids.some(id => !uuid.test(String(id)))) throw new Error('invalid_document_id');
return [{json:{batchExecutionApproved:true,companyId,companyName,sourceRoot,targets:ids.map((documentId,index)=>({documentId,sequence:index+1}))}}];

const definition = $('Build catalog targets').first().json;
const catalogResponse = $('Fetch batch catalog metadata').first().json;
const factsResponse = $input.first().json;
const normalizeArrayResponse = (response) => {
  const statusCode = Number(response.statusCode);
  let body = response.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch { return { ok: false, body: [] }; } }
  return { ok: Number.isInteger(statusCode) && statusCode >= 200 && statusCode < 300 && Array.isArray(body), body: Array.isArray(body) ? body : [] };
};
const catalogResult = normalizeArrayResponse(catalogResponse);
const factsResult = normalizeArrayResponse(factsResponse);
const requiredMetrics = new Set(['revenue', 'expense', 'net_result', 'cash_available']);
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const isolated = (target, stage, code) => ({ json: { outcome: 'isolated', sequence: target.sequence, documentId: target.documentId, periodMonth: target.periodMonth, stage, code, publishable: false } });
if (!catalogResult.ok) return definition.targets.map((target) => isolated(target, 'catalog', 'catalog_request_failed'));
if (!factsResult.ok) return definition.targets.map((target) => isolated(target, 'catalog', 'existing_facts_request_failed'));
return definition.targets.map((target) => {
  const matches = catalogResult.body.filter((document) => document?.id === target.documentId);
  if (matches.length !== 1) return isolated(target, 'catalog', matches.length === 0 ? 'catalog_document_missing' : 'catalog_document_not_unique');
  const document = matches[0];
  const etag = typeof document.source_etag === 'string' ? document.source_etag.trim() : '';
  const secondCopy = /2[ªa]?\s*via/i.test(String(document.file_name ?? ''));
  const valid = uuid.test(String(document.owner_id ?? ''))
    && document.company_id === target.companyId
    && document.provider === 'onedrive'
    && document.is_deleted === false
    && document.processing_status === 'pending'
    && document.file_name === target.fileName
    && /^\d{2}\.\d{4} Relat[oó]rio Gerencial Kawana\.xlsx$/i.test(document.file_name)
    && secondCopy === false
    && Number.isSafeInteger(document.file_size)
    && document.file_size >= 1
    && document.file_size <= target.maxFileSize
    && etag.length >= 1
    && etag.length <= 512
    && !/[\u0000-\u001f\u007f]/.test(etag)
    && typeof document.external_drive_id === 'string'
    && document.external_drive_id.length > 0
    && typeof document.external_file_id === 'string'
    && document.external_file_id.length > 0
    && typeof document.source_path === 'string'
    && (document.source_path === target.sourceRoot || document.source_path.startsWith(target.sourceRoot + '/'))
    && document.period_year === Number(target.periodMonth.slice(0, 4))
    && document.period_month === Number(target.periodMonth.slice(5, 7));
  if (!valid) return isolated(target, 'catalog', 'catalog_document_identity_mismatch');
  const currentFacts = factsResult.body.filter((row) => row?.document_id === target.documentId && row?.source_etag === etag);
  if (currentFacts.length > 0) {
    const metrics = new Set(currentFacts.map((row) => row?.metric));
    const complete = currentFacts.length === 4
      && metrics.size === 4
      && [...requiredMetrics].every((metric) => metrics.has(metric))
      && currentFacts.every((row) => row?.contract_version === 2 && ['pending_review', 'approved', 'rejected'].includes(row?.review_status));
    return { json: { outcome: complete ? 'already_processed' : 'isolated', sequence: target.sequence, documentId: target.documentId, periodMonth: target.periodMonth, stage: 'deduplication', code: complete ? 'current_etag_already_has_four_facts' : 'current_etag_has_partial_or_conflicting_facts', publishable: false } };
  }
  return { json: { outcome: 'eligible', sequence: target.sequence, target, catalog: { documentId: document.id, ownerId: document.owner_id, companyId: document.company_id, fileName: document.file_name, fileSize: document.file_size, sourceEtag: etag, externalDriveId: document.external_drive_id, externalFileId: document.external_file_id, sourcePath: document.source_path, periodMonth: target.periodMonth } } };
});

const item = $input.first();
const context = $('Process documents sequentially').item.json;
const invalid = (code) => [{ json: { outcome: 'isolated', sequence: context.sequence, documentId: context.target.documentId, periodMonth: context.target.periodMonth, stage: 'download', code, publishable: false } }];
if (!item.binary?.data) return invalid('graph_download_missing_binary');
const mimeType = String(item.binary.data.mimeType ?? '');
if (mimeType && mimeType !== 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet') return invalid('graph_download_invalid_mime');
if (context.catalog.fileSize < 1 || context.catalog.fileSize > context.target.maxFileSize || !context.catalog.fileName.toLowerCase().endsWith('.xlsx')) return invalid('document_size_or_extension_invalid');
return [{ json: { ...context, outcome: 'download_valid' }, binary: item.binary }];

const response = $input.first().json;
const context = $('Validate downloaded original XLSX').item.json;
const { target, catalog } = context;
const statusCode = Number(response.statusCode);
let extraction = response.body;
if (typeof extraction === 'string') { try { extraction = JSON.parse(extraction); } catch { extraction = null; } }
const requiredSheets = ['CAPA','RESUMO KWM','Fluxo de Caixa ' + target.periodMonth.slice(0,4),'ATIVO X PASSIVO KWN','ATIVOS KWN','PASSIVO KWN','RECEITAS X DESPESAS KWN','RECEITAS KWN','DESPESAS KWN','Itaú Kawana','Bradesco Invest Fácil Kawana','Bradesco Kawana','Caixa Kawana'];
const expectedSources = { cash_available: ['RESUMO KWM', 'B10'], revenue: ['RECEITAS X DESPESAS KWN', 'B23'], expense: ['RECEITAS X DESPESAS KWN', 'B8'], net_result: ['RECEITAS X DESPESAS KWN', 'B6'] };
const expectedReconciliations = new Set(['combined_result_equals_revenue_minus_expense','revenue_detail_matches_combined','expense_detail_matches_combined','summary_bank_components_match_total','bank_statement_balances_match_summary']);
const isolated = (code) => [{ json: { outcome: 'isolated', sequence: context.sequence, documentId: target.documentId, periodMonth: target.periodMonth, stage: 'worker_validation', code, publishable: false } }];
const decimalMinor = (amount) => { const match = String(amount ?? '').match(/^(-?)(\d+)\.(\d{2})$/); if (!match) return null; return ((match[1] === '-' ? -1n : 1n) * (BigInt(match[2]) * 100n + BigInt(match[3]))); };
try {
  if (statusCode !== 200) return isolated('worker_request_failed');
  if (!extraction || extraction.schemaVersion !== 'financial-extraction.v1' || extraction.status !== 'needs_review' || extraction.publishable !== false) throw new Error('invalid_extraction_contract');
  if (extraction.metadata?.mapping?.id !== target.mappingId || extraction.metadata?.mapping?.version !== target.mappingVersion || extraction.metadata?.mapping?.parserVersion !== target.parserVersion) throw new Error('mapping_or_parser_mismatch');
  if (extraction.metadata?.company?.id !== target.companyId || extraction.metadata?.company?.name !== target.companyName || extraction.metadata?.document?.id !== target.documentId || extraction.metadata?.document?.etag !== catalog.sourceEtag || extraction.metadata?.document?.fileName !== target.fileName || extraction.metadata?.periodMonth !== target.periodMonth) throw new Error('extraction_identity_mismatch');
  const sheets = extraction.metadata?.sheets;
  if (extraction.metadata?.sheetCount !== 13 || !Array.isArray(sheets) || sheets.length !== requiredSheets.length || requiredSheets.some((sheet) => !sheets.includes(sheet))) throw new Error('required_sheet_structure_mismatch');
  if (extraction.statistics?.formulaErrorCount !== 0 || extraction.statistics?.duplicateFactCount !== 0) throw new Error('formula_or_duplicate_fact_error');
  if (!Array.isArray(extraction.warnings) || extraction.warnings.some((warning) => warning?.severity === 'error')) throw new Error('extraction_contains_error_warning');
  if (!Array.isArray(extraction.reconciliations) || extraction.reconciliations.length !== 5) throw new Error('reconciliation_count_mismatch');
  const reconciliationCodes = new Set(extraction.reconciliations.map((item) => item?.code));
  if (reconciliationCodes.size !== 5 || extraction.reconciliations.some((item) => item?.status !== 'passed') || [...expectedReconciliations].some((code) => !reconciliationCodes.has(code))) throw new Error('financial_reconciliation_failed');
  if (!Array.isArray(extraction.facts) || !Array.isArray(extraction.bankTransactions)) throw new Error('invalid_extraction_payload');
  const canonical = extraction.facts.filter((fact) => fact?.includedInConsolidatedKpi === true && fact?.aggregationLevel === 'canonical');
  const metrics = Object.keys(expectedSources);
  if (canonical.length !== 4 || new Set(canonical.map((fact) => fact.metricCode)).size !== 4 || metrics.some((metric) => !canonical.some((fact) => fact.metricCode === metric))) throw new Error('missing_or_duplicate_required_canonical_fact');
  const factByMetric = Object.fromEntries(canonical.map((fact) => [fact.metricCode, fact]));
  const monthlyColumns = ['revenue','expense','net_result'].map(metric => String(factByMetric[metric]?.evidence?.cellAddress ?? '').replace(/[0-9]+$/, ''));
  if (new Set(monthlyColumns).size !== 1) throw new Error('monthly_columns_mismatch');
  const minors = Object.fromEntries(metrics.map((metric) => [metric, decimalMinor(factByMetric[metric]?.amount)]));
  if (metrics.some((metric) => minors[metric] === null || String(minors[metric]) !== String(factByMetric[metric]?.amountMinor))) throw new Error('invalid_financial_amount');
  if (minors.revenue < 0n || minors.expense < 0n || minors.cash_available < 0n || minors.net_result !== minors.revenue - minors.expense) throw new Error('invalid_financial_sign_or_result');
  const rows = metrics.map((metricCode) => {
    const fact = factByMetric[metricCode];
    const [expectedSheet, expectedCell] = expectedSources[metricCode];
    if (fact.companyId !== target.companyId || fact.companyName !== target.companyName || fact.documentId !== target.documentId || fact.sourceEtag !== catalog.sourceEtag || fact.periodMonth !== target.periodMonth || fact.currency !== 'BRL' || fact.reviewStatus !== 'needs_review' || fact.sourceScope !== 'business') throw new Error('invalid_canonical_fact');
    const sheet = String(fact.evidence?.sheet ?? '').trim();
    const sourceCell = String(fact.evidence?.cellAddress ?? '');
    if (sheet !== expectedSheet || (metricCode === 'cash_available' ? sourceCell !== 'B10' : !/^(?:[C-Z]|[A-Z]{2,3})(?:6|8|23|24)$/.test(sourceCell)) || (metricCode === 'revenue' && !/(23|24)$/.test(sourceCell)) || (metricCode === 'expense' && !/8$/.test(sourceCell)) || (metricCode === 'net_result' && !/6$/.test(sourceCell))) throw new Error('canonical_source_mismatch');
    const sourceRow = Number(sourceCell.match(/(\d+)$/)?.[1] ?? 0);
    const logicalKey = [target.documentId, catalog.sourceEtag, sheet, sourceCell, metricCode, target.periodMonth].join(':');
    if (!Number.isSafeInteger(sourceRow) || sourceRow <= 0 || fact.logicalKey !== logicalKey) throw new Error('invalid_fact_provenance');
    return { logical_key: logicalKey, company_id: target.companyId, company_name: target.companyName, month: target.periodMonth + '-01', metric_code: metricCode, amount: fact.amount, currency: 'BRL', sheet, source_row: sourceRow, source_cell: sourceCell, review_status: 'needs_review' };
  });
  return [{ json: { outcome: 'worker_valid', sequence: context.sequence, target, catalog, rows, reconciliationCount: 5, deferredFactCount: extraction.facts.length - rows.length, deferredBankTransactionCount: extraction.bankTransactions.length } }];
} catch (error) { return isolated(error instanceof Error ? error.message : 'invalid_extraction_contract'); }

const response = $input.first().json;
const context = $('Validate worker result before claim').item.json;
const statusCode = Number(response.statusCode);
let body = response.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch { body = null; } }
if (Array.isArray(body)) { if (body.length === 1) [body] = body; else body = null; }
const isolated = (code) => [{ json: { outcome: 'isolated', sequence: context.sequence, documentId: context.target.documentId, periodMonth: context.target.periodMonth, stage: 'claim', code, publishable: false } }];
if (!Number.isInteger(statusCode) || statusCode < 200 || statusCode >= 300) return isolated('claim_request_failed_or_duplicate');
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const valid = body?.has_document === true && body?.contract_version === 2 && body?.document_id === context.target.documentId && body?.owner_id === context.catalog.ownerId && body?.company_id === context.target.companyId && body?.company_name === context.target.companyName && body?.source_etag === context.catalog.sourceEtag && body?.file_name === context.target.fileName && body?.file_size === context.catalog.fileSize && body?.external_drive_id === context.catalog.externalDriveId && body?.external_file_id === context.catalog.externalFileId && body?.source_path === context.catalog.sourcePath && body?.extension === 'xlsx' && body?.period_month === context.target.periodMonth && uuid.test(String(body?.claim_id ?? ''));
if (!valid) return isolated('claimed_document_identity_mismatch');
return [{ json: { outcome: 'claim_valid', sequence: context.sequence, documentId: context.target.documentId, periodMonth: context.target.periodMonth, rpcPayload: { p_document_id: context.target.documentId, p_claim_id: body.claim_id, p_source_etag: context.catalog.sourceEtag, p_status: 'needs_review', p_rows: context.rows, p_note: 'financial-extraction.v1 canonical facts; manual sequential batch 12B', p_excerpt: null } } }];

const response = $input.first().json;
const context = $('Validate claim and build completion').item.json;
const statusCode = Number(response.statusCode);
let body = response.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch { body = null; } }
if (Array.isArray(body)) { if (body.length === 1) [body] = body; else body = null; }
const valid = Number.isInteger(statusCode) && statusCode >= 200 && statusCode < 300 && body?.success === true && body?.contract_version === 2 && body?.document_id === context.documentId && body?.status === 'needs_review' && Number.isInteger(body?.inserted_rows) && Number.isInteger(body?.unchanged_rows) && body.inserted_rows + body.unchanged_rows === 4 && body?.requires_approval === true;
if (!valid) return [{ json: { status: 'isolated', sequence: context.sequence, documentId: context.documentId, periodMonth: context.periodMonth, stage: 'completion', code: 'completion_unconfirmed', factsPersisted: null, publishable: false } }];
return [{ json: { status: 'pending_review', sequence: context.sequence, documentId: context.documentId, periodMonth: context.periodMonth, stage: 'completed', code: 'four_canonical_facts_ready_for_review', factsPersisted: body.inserted_rows, unchangedFacts: body.unchanged_rows, requiresApproval: true, publishable: false } }];

const config = $('Define approved batch inventory').first().json;
const response = $input.first().json;
let rows = response.body;
if (typeof rows === 'string') { try { rows = JSON.parse(rows); } catch { rows = null; } }
if (response.statusCode !== 200 || !Array.isArray(rows)) throw new Error('catalog_unavailable');
const targets = config.targets.map(target => {
 const matches = rows.filter(row => row.id === target.documentId);
 if (matches.length !== 1) throw new Error('catalog_identity_missing_or_duplicate');
 const row = matches[0];
 if (row.company_id !== config.companyId || !Number.isInteger(row.period_year) || row.period_year < 2000 || row.period_year > 2100 || !Number.isInteger(row.period_month) || row.period_month < 1 || row.period_month > 12) throw new Error('catalog_scope_or_period_invalid');
 return {...target,companyId:config.companyId,companyName:config.companyName,sourceRoot:config.sourceRoot,fileName:row.file_name,periodMonth:`${row.period_year}-${String(row.period_month).padStart(2,'0')}`,mappingId:'kawana-management-report',mappingVersion:'2',parserVersion:'12A.3',maxFileSize:8388608};
});
return [{json:{...config,targets}}];
